# Windows compatibility shim for the native-Windows Frappe spike (no upstream source changes).
# Only defines names that Frappe/ERPNext reference at import time; behaviour is NOT emulated.
import os, signal, sys
if sys.platform == "win32":
    for _name, _value in (("SIGKILL", signal.SIGTERM), ("SIGALRM", 14), ("SIGHUP", 1), ("SIGQUIT", 3), ("SIGUSR1", 10), ("SIGUSR2", 12)):
        if not hasattr(signal, _name):
            setattr(signal, _name, _value)
    os.add_dll_directory(os.path.join(os.path.dirname(__file__), "MySQLdb"))
    if not hasattr(os, "register_at_fork"):
        os.register_at_fork = lambda **kwargs: None   # no fork on Windows: fork hooks never fire
    import faulthandler
    if not hasattr(faulthandler, "register"):
        faulthandler.register = lambda *args, **kwargs: None   # signal-triggered dumps unavailable on Windows
    if not hasattr(os, "nice"):
        os.nice = lambda increment: 0   # priority is set per process (BelowNormal) on Windows
